#!/usr/bin/env bash
# Checks that the images built from src/ and from the repository root follow the build context convention in
# .github/README.md, and that each container tool given as an argument sends them the same context. Prints each
# context's size.
#
# Usage: check-image-contexts.sh [tool...]   (default: docker podman)
#        check-image-contexts.sh --write     (regenerates src/.dockerignore and .dockerignore from the allowlists)
set -euo pipefail

repo_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"

# The images built from each shared context, by Dockerfile relative to the context. Add an image here when you add
# one that builds from src/ or the repository root.
src_images=(
  Designer/backend/Migrations.Dockerfile
  Runtime/gateway/Dockerfile
  Runtime/kubernetes-wrapper/src/Dockerfile
  Runtime/localtest/Dockerfile
  Runtime/operator/Dockerfile
  Runtime/operator/Dockerfile.fakes
  Runtime/pdf3/Dockerfile.proxy
  Runtime/pdf3/Dockerfile.worker
  Runtime/workflow-engine/Dockerfile
  Runtime/workflow-engine-app/Dockerfile
)
root_images=(
  src/AI/assistant/dockerfile
  src/Designer/Dockerfile
  src/ci/github-runner/Dockerfile.coordinator
)

# Sets the context's directory, prefix for display, images, size budgets, and the shared file's exclusions and the
# paths it keeps despite them. A context above its budget likely sends more than the images need.
load_context() {
  case "$1" in
  src)
    context_dir="${repo_root}/src" prefix="src/" images=("${src_images[@]}")
    max_context_bytes=$((20 * 1024 * 1024)) max_shared_context_bytes=$((64 * 1024 * 1024))
    # localtest serves files from a dist/ directory, so the shared file cannot leave dist/ out here.
    excludes=("${common_excludes[@]}") keeps=()
    ;;
  root)
    context_dir="${repo_root}" prefix="" images=("${root_images[@]}")
    max_context_bytes=$((64 * 1024 * 1024)) max_shared_context_bytes=$((96 * 1024 * 1024))
    # Rust keeps binaries' sources in src/bin/, which the .NET build output exclusion would leave out.
    excludes=("${common_excludes[@]}" '**/dist') keeps=('!src/ci/github-runner/coordinator/src/bin/**')
    ;;
  esac
}
contexts=(src root)
common_excludes=(
  '**/.DS_Store' '**/.cache' '**/.git' '**/.idea' '**/.vscode' '**/bin' '**/obj' '**/node_modules' '**/target'
  '**/.venv' '**/__pycache__' '**/*.pyc' '**/.pytest_cache'
)

# Prints the context's .dockerignore: every path an image's allowlist re-includes, without build output.
shared_dockerignore() {
  echo '# Generated by .github/scripts/check-image-contexts.sh --write. Compose and plain podman builds read this'
  echo "# file instead of an image's own Dockerfile.dockerignore, so it allows what any image built here needs."
  echo '**'
  for image in "${images[@]}"; do
    grep -h '^!' "${context_dir}/${image}.dockerignore" || true
  done | LC_ALL=C sort -u
  printf '%s\n' "${excludes[@]}" ${keeps[@]+"${keeps[@]}"}
}

if [ "${1:-}" = --write ]; then
  for context in "${contexts[@]}"; do
    load_context "${context}"
    shared_dockerignore >"${context_dir}/.dockerignore"
  done
  exit 0
fi

if [ "$#" -gt 0 ]; then
  tools=("$@")
else
  tools=(docker podman)
fi

failures=0
fail() {
  echo "::error::$*"
  failures=$((failures + 1))
}

work_dir="$(mktemp -d)"
probe_dir="" probe_tool="" probe_container="" probe_tag=""
cleanup() {
  if [ -n "${probe_container}" ]; then
    "${probe_tool}" rm --force "${probe_container}" >/dev/null 2>&1 || true
  fi
  if [ -n "${probe_tag}" ]; then
    "${probe_tool}" rmi --force "${probe_tag}" >/dev/null 2>&1 || true
  fi
  rm -rf "${work_dir}" "${probe_dir}"
}
trap cleanup EXIT

for context in "${contexts[@]}"; do
  load_context "${context}"
  for image in "${images[@]}"; do
    allowlist="${context_dir}/${image}.dockerignore"
    if [ ! -f "${allowlist}" ]; then
      fail "${prefix}${image} has no allowlist. Add ${prefix}${image}.dockerignore."
      continue
    fi
    # Podman does not re-include a file through **/ inside a directory that an earlier pattern excluded.
    if grep -nE '^[[:space:]]*!.*\*\*/' "${allowlist}" >"${work_dir}/reincludes"; then
      fail "${prefix}${image}.dockerignore re-includes through **/, which Podman matches differently: $(paste -sd ' ' "${work_dir}/reincludes")"
    fi
    # Re-including a directory sends all of it, so a narrower re-include below it means the directory is too wide.
    if awk '/^!/ { path = substr($0, 2); sub(/\/$/, "", path); paths[NR] = path }
      END {
        for (i in paths) for (j in paths)
          if (i != j && paths[i] !~ /[*?[]/ && index(paths[j], paths[i] "/") == 1 && paths[j] != paths[i] "/**") {
            print "!" paths[i]; exit 1
          }
      }' "${allowlist}" >"${work_dir}/parents"; then :; else
      fail "${prefix}${image}.dockerignore re-includes all of $(cat "${work_dir}/parents"). Re-include the paths below it instead."
    fi
  done
done
if [ "${failures}" -gt 0 ]; then
  exit 1
fi

is_podman() {
  "$1" --version 2>/dev/null | grep -qi podman
}

# Writes the files that a tool sends as the context, as "<size> <path>" lines, to the given file. With an allowlist,
# the tool builds the way Docker and devenv do. Without one, it builds the way Compose and plain podman builds do.
list_context() {
  local tool="$1" output="$2" allowlist="${3:-}"
  local args=(build --quiet --file "${probe_dir}/Dockerfile")
  rm -f "${probe_dir}/Dockerfile.dockerignore"
  if [ -n "${allowlist}" ]; then
    cp "${allowlist}" "${probe_dir}/Dockerfile.dockerignore"
    if is_podman "${tool}"; then
      args+=(--ignorefile "${allowlist}")
    fi
  fi
  probe_tool="${tool}" probe_tag="image-context-probe:$$"
  "${tool}" "${args[@]}" --tag "${probe_tag}" "${context_dir}" >/dev/null
  probe_container="$("${tool}" create "${probe_tag}" probe)"
  mkdir -p "${work_dir}/export"
  # A failed export must fail the check, rather than pass as an empty context.
  "${tool}" export "${probe_container}" | tar -xf - -C "${work_dir}/export" ctx
  "${tool}" rm "${probe_container}" >/dev/null
  probe_container=""
  "${tool}" rmi "${probe_tag}" >/dev/null
  probe_tag=""
  (cd "${work_dir}/export/ctx" && find . ! -type d -printf '%s %P\n' | LC_ALL=C sort -k2) >"${output}"
  rm -rf "${work_dir}/export"
}

# Prints a listing's row and checks it against the budget and the first tool's listing.
report() {
  local name="$1" tool="$2" listing="$3" first="$4" budget="$5" files bytes
  files="$(wc -l <"${listing}")"
  bytes="$(awk '{ sum += $1 } END { print sum + 0 }' "${listing}")"
  printf '%-50s %-12s %8d %10d\n' "${name}" "$(basename "${tool}")" "${files}" "$((bytes / 1024))"
  if [ "${bytes}" -gt "${budget}" ]; then
    fail "${tool} sends $((bytes / 1024 / 1024)) MiB as the context of ${name}, above the $((budget / 1024 / 1024)) MiB budget."
  fi
  if [ -n "${first}" ] && ! diff -u "${first}" "${listing}" >"${work_dir}/diff"; then
    fail "$(basename "${tools[0]}") and ${tool} send different contexts for ${name}:"
    head -n 40 "${work_dir}/diff"
  fi
}

printf '%-50s %-12s %8s %10s\n' Context Tool Files KiB
for context in "${contexts[@]}"; do
  load_context "${context}"
  shared_ignore="${prefix}.dockerignore"
  if ! shared_dockerignore | diff -u - "${context_dir}/.dockerignore" >"${work_dir}/diff" 2>&1; then
    fail "${shared_ignore} is out of date. Run .github/scripts/check-image-contexts.sh --write."
    head -n 40 "${work_dir}/diff"
  fi
  # Podman would read .containerignore before .dockerignore, and Compose does not read it at all.
  if [ -e "${context_dir}/.containerignore" ]; then
    fail "Remove ${prefix}.containerignore. ${shared_ignore} is the context's ignore file."
  fi

  # The probe must be inside the context, since remote Podman reads a Dockerfile's ignore file only there.
  probe_dir="$(mktemp -d "${context_dir}/.image-context-probe.XXXXXX")"
  printf 'FROM scratch\nCOPY . /ctx/\n' >"${probe_dir}/Dockerfile"

  first=""
  for tool in "${tools[@]}"; do
    listing="${work_dir}/shared-$(basename "${tool}").txt"
    list_context "${tool}" "${listing}"
    report "${shared_ignore}" "${tool}" "${listing}" "${first}" "${max_shared_context_bytes}"
    first="${first:-${listing}}"
  done
  shared_listing="${work_dir}/shared.txt"
  mv "${first}" "${shared_listing}"

  for image in "${images[@]}"; do
    first=""
    for tool in "${tools[@]}"; do
      listing="${work_dir}/$(basename "${tool}").txt"
      list_context "${tool}" "${listing}" "${context_dir}/${image}.dockerignore"
      report "${prefix}${image}" "${tool}" "${listing}" "${first}" "${max_context_bytes}"
      first="${first:-${listing}}"
    done
    # Compose and plain podman builds get the shared context, so it must hold all that the image needs.
    if missing="$(LC_ALL=C comm -23 <(cut -d' ' -f2- "${first}") <(cut -d' ' -f2- "${shared_listing}"))" &&
      [ -n "${missing}" ]; then
      fail "${shared_ignore} leaves out files that ${prefix}${image} needs: $(head -n 10 <<<"${missing}" | paste -sd ' ')"
    fi
  done

  rm -rf "${probe_dir}"
  probe_dir=""
done

if [ "${failures}" -gt 0 ]; then
  echo "${failures} problem(s) with the image build contexts. See .github/README.md."
  exit 1
fi
